                                name,
                                query,
                                context
                            );
                    } else if (
                        IERC165(dnsresolver).supportsInterface(
                            IExtendedResolver.resolve.selector
                        )
                    ) {
                        return IExtendedResolver(dnsresolver).resolve(name, query);
                    } else {
                        (bool ok, bytes memory ret) = address(dnsresolver)
                            .staticcall(query);
